// ============================================================================
// CONFIGURATION
// ============================================================================

var CONFIG = {
  CACHE_TTL: {
    READ: 300,          // 5 minutes for reads
    WRITE: 30,          // 30 seconds after writes
    BATCH: 600,         // 10 minutes for full dataset
    INDEX: 600,         // 10 minutes for indexes
    PREVIEW: 120        // 2 minutes for preview data
  },
  THROTTLE: {
    MAX_REQUESTS_PER_MINUTE: 30,
    WINDOW_MS: 60000
  },
  PAGINATION: {
    DEFAULT_PAGE_SIZE: 50,
    PREVIEW_SIZE: 20,
    MAX_BATCH_SIZE: 1000
  },
  LOCK_TIMEOUT_MS: 30000,
  MAX_CACHE_ENTRIES: 50,
  LOGGING: {
    ENABLE_SHEET_LOG: false,        // Default disabled to protect spreadsheet write lock & API quota
    LOG_READ_OPERATIONS: false,    // Reads/pings NEVER write to sheets (0ms overhead via console.info)
    MAX_LOG_ENTRIES: 500,          // Retention ceiling
    BATCH_TRIM_THRESHOLD: 100      // Only trim when backlog exceeds ceiling + threshold
  }
};

// ============================================================================
